-- Conversation Intelligence cache tablosu\r\n-- GPT-4o analiz sonuçlarını cache'ler, her 24 saatte bir yenilenir\r\nCREATE TABLE IF NOT EXISTS conversation_insights (\r\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\r\n    tenant_id UUID REFERENCES tenants(id) ON DELETE CASCADE,\r\n    period_start TEXT NOT NULL,\r\n    period_end TEXT NOT NULL,\r\n    insights JSONB NOT NULL DEFAULT '{}',\r\n    total_calls INTEGER DEFAULT 0,\r\n    created_at TIMESTAMPTZ DEFAULT now()\r\n);\r\n\r\n-- Index for tenant lookups\r\nCREATE INDEX IF NOT EXISTS idx_conversation_insights_tenant \r\n    ON conversation_insights(tenant_id, created_at DESC);\r\n\r\n-- RLS\r\nALTER TABLE conversation_insights ENABLE ROW LEVEL SECURITY;\r\n\r\nCREATE POLICY \"Tenant members can read conversation_insights\" ON conversation_insights\r\n    FOR SELECT USING (tenant_id IN (SELECT tenant_id FROM profiles WHERE id = auth.uid()));\r\n\r\nCREATE POLICY \"Service role can manage conversation_insights\" ON conversation_insights\r\n    FOR ALL USING (true) WITH CHECK (true);\r\n
